import Foundation

/// Learned "is this fix right?" model (logistic regression over 11 facts about a fix).
/// Generated by `tools/train learn` from real typo data. Don't edit by hand; retrain instead.
/// Facts, in order: slip cost, cost per letter, lead over runner-up, word frequency, fits left word, fits right word, length, candidates in reach, macOS knows it, capitalised, contraction.
enum FixGate {
    /// Bold fixes more of your messy words; Careful only fixes when it's very sure
    enum Mode: String { case bold, careful }
    static var mode: Mode = .bold
    static var threshold: Double { mode == .bold ? boldThreshold : carefulThreshold }
    static var forceOff = false   // training/testing: use the hand-written rules instead
    static var isTrained: Bool { !weights.isEmpty && !forceOff }

    static let boldThreshold = 0.68
    static let carefulThreshold = 0.85
    static let mean: [Double] = [0.653508, 0.118058, 2.524976, 7.921023, 1.557879, 1.391842, 6.613862, 3.586865, 0.306349, 0.133339, 0.004836]
    static let scale: [Double] = [0.353816, 0.080195, 0.882377, 1.274187, 1.495258, 1.492713, 2.905407, 1.825975, 0.460976, 0.339941, 0.069371]
    static let weights: [Double] = [-0.963025, -0.419046, 0.785159, 0.826501, 0.200374, 0.293532, 0.578489, 0.051196, -0.737077, -0.641598, 0.037640]
    static let bias = 1.829155

    /// Chance (0-1) that fixing to the best candidate is right
    static func probability(_ x: [Double]) -> Double {
        var z = bias
        for i in 0..<weights.count { z += weights[i] * (x[i] - mean[i]) / scale[i] }
        return 1 / (1 + exp(-z))
    }
}
